1	import { privateMatch, rulesPresets, type ValidationResult } from "./rules.js";
2	import {
3	  ENGAGEMENT_RANGE_TILES,
4	  SIGHT_RADIUS_TILES,
5	  travelTargets,
6	  WORLD_STEPS_PER_SECOND,
7	  type ShipTuning,
8	} from "./sailing.js";
9	import { insideIsland, isNavigable, Terrain, terrainAt, type SeaMapDefinition } from "./seaMap.js";
10	
11	const UNREACHABLE = Number.MAX_SAFE_INTEGER;
12	
13	/** No island rectangle may be larger than this many tiles on a side: the slice's islands are small (§18). */
14	export const MAX_ISLAND_SIDE_TILES = 16;
15	
16	/**
17	 * Octile path costs for one tile step, in sub-units: straight is a tile's side, diagonal its side times √2, rounded to
18	 * the nearest integer by an integer square root (no floating-point `Math.sqrt` in the pure packages). For 256
19	 * sub-units a tile, 256 and 362.
20	 */
21	export function octileStepCosts(subUnitsPerTile: number): { readonly straight: number; readonly diagonal: number } {
22	  const square = 2 * subUnitsPerTile * subUnitsPerTile;
23	  let root = 0;
24	  while ((root + 1) * (root + 1) <= square) root++;
25	  // Round half up: √square ≥ root + ½ exactly when square − root² > root.
26	  return { straight: subUnitsPerTile, diagonal: square - root * root > root ? root + 1 : root };
27	}
28	
29	/**
30	 * Shortest sea-path cost in sub-units from one tile to every tile, over navigable tiles, moving in eight directions.
31	 * A diagonal step needs both tiles beside it free, since a hull cannot squeeze between two blocked corners.
32	 */
33	export function seaPathCosts(map: SeaMapDefinition, fromX: number, fromY: number): Float64Array {
34	  const width = map.widthTiles;
35	  const costs = new Float64Array(width * map.heightTiles).fill(UNREACHABLE);
36	  if (!isNavigable(map, fromX, fromY)) return costs;
37	  const step = octileStepCosts(map.subUnitsPerTile);
38	  const heap = new MinHeap();
39	  const start = fromY * width + fromX;
40	  costs[start] = 0;
41	  heap.push(0, start);
42	  while (heap.size > 0) {
43	    const [cost, index] = heap.pop();
44	    if (cost > costs[index]!) continue;
45	    const x = index % width;
46	    const y = (index - x) / width;
47	    for (let dy = -1; dy <= 1; dy++) {
48	      for (let dx = -1; dx <= 1; dx++) {
49	        if (dx === 0 && dy === 0) continue;
50	        const nx = x + dx;
51	        const ny = y + dy;
52	        if (!isNavigable(map, nx, ny)) continue;
53	        const diagonal = dx !== 0 && dy !== 0;
54	        if (diagonal && (!isNavigable(map, x + dx, y) || !isNavigable(map, x, y + dy))) continue;
55	        const next = cost + (diagonal ? step.diagonal : step.straight);
56	        const target = ny * width + nx;
57	        if (next < costs[target]!) {
58	          costs[target] = next;
59	          heap.push(next, target);
60	        }
61	      }
62	    }
63	  }
64	  return costs;
65	}
66	
67	/** Seconds at full speed for a path cost, rounded down to milliseconds. */
68	export function travelSeconds(cost: number, tuning: ShipTuning): number {
69	  return Math.floor((cost * 1000) / (tuning.maxSpeed * WORLD_STEPS_PER_SECOND)) / 1000;
70	}
71	
72	export interface PointOfInterest {
73	  readonly label: string;
74	  readonly tileX: number;
75	  readonly tileY: number;
76	}
77	
78	export interface SeaMapReport {
79	  /** Each island's nearest other island by sea, dock to dock. */
80	  readonly nearestIsland: readonly { island: string; nearest: string; seconds: number }[];
81	  /** The longest shortest trip between any two docks or spawn slots. */
82	  readonly longestCrossing: { from: string; to: string; seconds: number };
83	  /** Each spawn slot's nearest dock. */
84	  readonly firstDock: readonly { slot: number; dock: string; seconds: number }[];
85	}
86	
87	export interface SeaMapRules {
88	  readonly islands: number;
89	  readonly spawnSlots: number;
90	}
91	
92	export const sliceSeaRules: SeaMapRules = { islands: rulesPresets.slice.islands, spawnSlots: privateMatch.maxPlayers };
93	
94	/**
95	 * Checks a map against §2 and §3: four small islands, each with a dock; shoals; eight outer-sea spawn slots out of
96	 * each other's engagement range; every dock and slot reachable by sea; neighbouring islands 20–40 s apart and no
97	 * useful crossing over 90 s at full speed; and a dock within 40 s of every slot.
98	 */
99	export function validateSeaMap(map: SeaMapDefinition, tuning: ShipTuning, rules: SeaMapRules = sliceSeaRules): ValidationResult<SeaMapReport> {
100	  const issues: string[] = [];
101	  const { islands, docks, spawnSlots } = map;
102	  const tileCentre = Math.floor(map.subUnitsPerTile / 2);
103	
104	  if (tuning.hullHalfSize >= tileCentre) issues.push(`ship hull half-size ${tuning.hullHalfSize} does not fit inside one tile`);
105	  if (SIGHT_RADIUS_TILES <= ENGAGEMENT_RANGE_TILES) issues.push("the sight radius must be larger than the engagement range");
106	
107	  if (islands.length !== rules.islands) issues.push(`${islands.length} islands, not ${rules.islands}`);
108	  islands.forEach((island, index) => {
109	    if (island.widthTiles > MAX_ISLAND_SIDE_TILES || island.heightTiles > MAX_ISLAND_SIDE_TILES) {
110	      issues.push(`${island.name}: ${island.widthTiles} × ${island.heightTiles} tiles is not a small island`);
111	    }
112	    if (island.tileX < 0 || island.tileY < 0 || island.tileX + island.widthTiles > map.widthTiles || island.tileY + island.heightTiles > map.heightTiles) {
113	      issues.push(`${island.name}: outside the map`);
114	    }
115	    for (const other of islands.slice(index + 1)) {
116	      const apart =
117	        island.tileX + island.widthTiles <= other.tileX ||
118	        other.tileX + other.widthTiles <= island.tileX ||
119	        island.tileY + island.heightTiles <= other.tileY ||
120	        other.tileY + other.heightTiles <= island.tileY;
121	      if (!apart) issues.push(`${island.name} and ${other.name} overlap`);
122	    }
123	    if (!docks.some((dock) => dock.island === index)) issues.push(`${island.name}: no dock`);
124	  });
125	
126	  let landTiles = 0;
127	  let shoalTiles = 0;
128	  for (let tileY = 0; tileY < map.heightTiles; tileY++) {
129	    for (let tileX = 0; tileX < map.widthTiles; tileX++) {
130	      const kind = terrainAt(map, tileX, tileY);
131	      if (kind === Terrain.Shoal) shoalTiles++;
132	      if (kind !== Terrain.Land) continue;
133	      landTiles++;
134	      const owners = islands.filter((island) => insideIsland(island, tileX, tileY)).length;
135	      if (owners !== 1) issues.push(`land at ${tileX},${tileY} lies in ${owners} island rectangles, not one`);
136	    }
137	  }
138	  if (landTiles === 0) issues.push("no land");
139	  if (shoalTiles === 0) issues.push("no shoals");
140	
141	  const neighbours = (tileX: number, tileY: number) => [
142	    [tileX + 1, tileY],
143	    [tileX - 1, tileY],
144	    [tileX, tileY + 1],
145	    [tileX, tileY - 1],
146	  ] as const;
147	  for (const dock of docks) {
148	    const where = `dock at ${dock.tileX},${dock.tileY}`;
149	    const island = islands[dock.island];
150	    if (island === undefined) {
151	      issues.push(`${where}: outside every island rectangle`);
152	      continue;
153	    }
154	    const touches = (kind: Terrain) =>
155	      neighbours(dock.tileX, dock.tileY).some(([x, y]) => terrainAt(map, x, y) === kind && (kind !== Terrain.Land || insideIsland(island, x, y)));
156	    if (!touches(Terrain.Land)) issues.push(`${where}: not beside ${island.name}'s land`);
157	    if (!touches(Terrain.Sea)) issues.push(`${where}: no open sea beside it`);
158	  }
159	
160	  if (spawnSlots.length !== rules.spawnSlots) issues.push(`${spawnSlots.length} spawn slots, not ${rules.spawnSlots}`);
161	  const archipelago = boundsOf(islands);
162	  spawnSlots.forEach((slot, index) => {
163	    const where = `spawn slot ${index} at ${slot.tileX},${slot.tileY}`;
164	    if (terrainAt(map, slot.tileX, slot.tileY) !== Terrain.Sea) issues.push(`${where}: not on open sea`);
165	    if (
166	      archipelago !== undefined &&
167	      slot.tileX >= archipelago.minX &&
168	      slot.tileX <= archipelago.maxX &&
169	      slot.tileY >= archipelago.minY &&
170	      slot.tileY <= archipelago.maxY
171	    ) {
172	      issues.push(`${where}: inside the archipelago, not on the outer sea`);
173	    }
174	    spawnSlots.slice(index + 1).forEach((other, offset) => {
175	      const dx = other.tileX - slot.tileX;
176	      const dy = other.tileY - slot.tileY;
177	      if (dx * dx + dy * dy <= ENGAGEMENT_RANGE_TILES * ENGAGEMENT_RANGE_TILES) {
178	        issues.push(`${where}: within engagement range of slot ${index + 1 + offset}`);
179	      }
180	    });
181	  });
182	  if (issues.length > 0) return { ok: false, issues };
183	
184	  // Travel: one shortest-path search from every dock and spawn slot.
185	  const points: PointOfInterest[] = [
186	    ...docks.map((dock) => ({ label: `${islands[dock.island]!.name} ${dock.side} dock`, tileX: dock.tileX, tileY: dock.tileY })),
187	    ...spawnSlots.map((slot, index) => ({ label: `spawn slot ${index}`, tileX: slot.tileX, tileY: slot.tileY })),
188	  ];
189	  const costs = points.map((point) => seaPathCosts(map, point.tileX, point.tileY));
190	  const between = (from: number, to: number) => costs[from]![points[to]!.tileY * map.widthTiles + points[to]!.tileX]!;
191	
192	  const origin = docks.length;
193	  points.forEach((point, index) => {
194	    if (between(origin, index) === UNREACHABLE) issues.push(`${point.label} at ${point.tileX},${point.tileY}: not reachable by sea from spawn slot 0`);
195	  });
196	  if (issues.length > 0) return { ok: false, issues };
197	
198	  const nearestIsland = islands.map((island, index) => {
199	    let best = { nearest: "", cost: UNREACHABLE };
200	    docks.forEach((from, fromIndex) => {
201	      if (from.island !== index) return;
202	      docks.forEach((to, toIndex) => {
203	        if (to.island === index) return;
204	        const cost = between(fromIndex, toIndex);
205	        if (cost < best.cost) best = { nearest: islands[to.island]!.name, cost };
206	      });
207	    });
208	    return { island: island.name, nearest: best.nearest, seconds: travelSeconds(best.cost, tuning) };
209	  });
210	  for (const entry of nearestIsland) {
211	    if (entry.seconds < travelTargets.neighbourIslandMinSeconds || entry.seconds > travelTargets.neighbourIslandMaxSeconds) {
212	      issues.push(
213	        `${entry.island}: its nearest island, ${entry.nearest}, is ${entry.seconds} s away, outside ${travelTargets.neighbourIslandMinSeconds}–${travelTargets.neighbourIslandMaxSeconds} s`,
214	      );
215	    }
216	  }
217	
218	  let longest = { from: "", to: "", cost: 0 };
219	  points.forEach((from, fromIndex) => {
220	    points.forEach((to, toIndex) => {
221	      const cost = between(fromIndex, toIndex);
222	      if (cost > longest.cost) longest = { from: from.label, to: to.label, cost };
223	    });
224	  });
225	  const longestCrossing = { from: longest.from, to: longest.to, seconds: travelSeconds(longest.cost, tuning) };
226	  if (longestCrossing.seconds > travelTargets.longestCrossingMaxSeconds) {
227	    issues.push(`the crossing from ${longest.from} to ${longest.to} takes ${longestCrossing.seconds} s, over ${travelTargets.longestCrossingMaxSeconds} s`);
228	  }
229	
230	  const firstDock = spawnSlots.map((_, slot) => {
231	    let best = { dock: "", cost: UNREACHABLE };
232	    docks.forEach((_, dockIndex) => {
233	      const cost = between(origin + slot, dockIndex);
234	      if (cost < best.cost) best = { dock: points[dockIndex]!.label, cost };
235	    });
236	    return { slot, dock: best.dock, seconds: travelSeconds(best.cost, tuning) };
237	  });
238	  for (const entry of firstDock) {
239	    if (entry.seconds > travelTargets.firstDockMaxSeconds) {
240	      issues.push(`spawn slot ${entry.slot}: the nearest dock is ${entry.seconds} s away, over ${travelTargets.firstDockMaxSeconds} s`);
241	    }
242	  }
243	
244	  return issues.length > 0 ? { ok: false, issues } : { ok: true, value: { nearestIsland, longestCrossing, firstDock } };
245	}
246	
247	function boundsOf(islands: SeaMapDefinition["islands"]) {
248	  if (islands.length === 0) return undefined;
249	  return {
250	    minX: Math.min(...islands.map((island) => island.tileX)),
251	    minY: Math.min(...islands.map((island) => island.tileY)),
252	    maxX: Math.max(...islands.map((island) => island.tileX + island.widthTiles - 1)),
253	    maxY: Math.max(...islands.map((island) => island.tileY + island.heightTiles - 1)),
254	  };
255	}
256	
257	/** A binary min-heap of (cost, index) pairs for the path search. */
258	class MinHeap {
259	  private readonly costs: number[] = [];
260	  private readonly indexes: number[] = [];
261	
262	  get size(): number {
263	    return this.costs.length;
264	  }
265	
266	  push(cost: number, index: number): void {
267	    this.costs.push(cost);
268	    this.indexes.push(index);
269	    let child = this.costs.length - 1;
270	    while (child > 0) {
271	      const parent = (child - 1) >> 1;
272	      if (this.costs[parent]! <= cost) break;
273	      this.swap(child, parent);
274	      child = parent;
275	    }
276	  }
277	
278	  pop(): [number, number] {
279	    const top: [number, number] = [this.costs[0]!, this.indexes[0]!];
280	    const lastCost = this.costs.pop()!;
281	    const lastIndex = this.indexes.pop()!;
282	    if (this.costs.length > 0) {
283	      this.costs[0] = lastCost;
284	      this.indexes[0] = lastIndex;
285	      let parent = 0;
286	      for (;;) {
287	        const left = 2 * parent + 1;
288	        const right = left + 1;
289	        let smallest = parent;
290	        if (left < this.costs.length && this.costs[left]! < this.costs[smallest]!) smallest = left;
291	        if (right < this.costs.length && this.costs[right]! < this.costs[smallest]!) smallest = right;
292	        if (smallest === parent) break;
293	        this.swap(parent, smallest);
294	        parent = smallest;
295	      }
296	    }
297	    return top;
298	  }
299	
300	  private swap(a: number, b: number): void {
301	    [this.costs[a], this.costs[b]] = [this.costs[b]!, this.costs[a]!];
302	    [this.indexes[a], this.indexes[b]] = [this.indexes[b]!, this.indexes[a]!];
303	  }
304	}
305

